// Settings for this workflow. Generated by scripts/build_n8n_workflows.py.
return [{ json: {
  "supabase_url": "https://YOUR-PROJECT.supabase.co",
  "signing_secret": "YOUR-SLACK-SIGNING-SECRET",
  "alerts_channel": "YOUR-ALERTS-CHANNEL-ID",
  "intake_address": "intake@example.com",
  "allowlist": [
    "customer@example.com"
  ],
  "company_name": "Copperline Plumbing & Air",
  "email_footer": "--\nAutomated demo reply from a fictional company (Copperline Plumbing & Air). No real service is offered."
}, binary: $input.first().binary }];

// Slack signs every request it sends. Rebuild the signed text so the next step can check it.
const request = $('Slack action').first();
const headers = request.json.headers || {};
const timestamp = headers['x-slack-request-timestamp'] || '';
const signature = headers['x-slack-signature'] || '';

const binaryKey = Object.keys($input.first().binary || {})[0];
const raw = binaryKey ? (await this.helpers.getBinaryDataBuffer(0, binaryKey)).toString('utf8') : '';

const payloadText = request.json.body?.payload;
const ageSeconds = Math.abs(Date.now() / 1000 - Number(timestamp));

return [{
  json: {
    base_string: `v0:${timestamp}:${raw}`,
    signature,
    has_raw_body: raw.length > 0,
    fresh: Number.isFinite(ageSeconds) && ageSeconds < 300,  // reject replays older than 5 minutes
    payload: payloadText ? JSON.parse(payloadText) : null,
  },
}];

// Which button was clicked, on which price, by whom.
const payload = $('Read Slack request').first().json.payload;
const action = payload?.actions?.[0];
if (!action || !['approve_price', 'reject_price'].includes(action.action_id)) return [];
const id = Number(action.value);
if (!Number.isInteger(id) || id <= 0) return [];

return [{
  json: {
    approved: action.action_id === 'approve_price',
    approval_id: id,
    user: payload.user?.name || payload.user?.username || payload.user?.id || 'someone',
    channel: payload.channel?.id || payload.container?.channel_id || null,
    message_ts: payload.message?.ts || payload.container?.message_ts || null,
  },
}];

// Slack layout for a price waiting for the owner's approval. Pasted into the
// n8n Code nodes by scripts/build_n8n_workflows.py, so workflow 1 (posting
// the draft) and workflow 3 (showing the outcome) always look the same.

function whoLine(lead) {
  const contact = [lead.email, lead.phone].filter(Boolean).join(', ') || 'no contact';
  return `${lead.name || 'Unknown'} (${contact}, zip ${lead.zip || 'unknown'})`;
}

function priceApprovalBlocks(p, outcome) {
  const quote = text => String(text || '').split('\n').map(line => '>' + line).join('\n');
  const blocks = [
    { type: 'section', text: { type: 'mrkdwn', text: `:moneybag: *Price waiting for approval*\n${p.who}\n${p.summary || ''}` } },
    { type: 'section', text: { type: 'mrkdwn', text: `*Draft reply to the customer*\n${quote(p.reply)}` } },
  ];
  if (outcome) {
    blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: outcome }] });
  } else {
    blocks.push({
      type: 'actions',
      elements: [
        { type: 'button', style: 'primary', action_id: 'approve_price', value: String(p.approval_id),
          text: { type: 'plain_text', text: 'Approve and send' } },
        { type: 'button', style: 'danger', action_id: 'reject_price', value: String(p.approval_id),
          text: { type: 'plain_text', text: 'Reject' },
          confirm: {
            title: { type: 'plain_text', text: 'Reject this price?' },
            text: { type: 'mrkdwn', text: 'Nothing is sent to the customer and the lead is handed to you.' },
            confirm: { type: 'plain_text', text: 'Reject' },
            deny: { type: 'plain_text', text: 'Cancel' },
          } },
      ],
    });
  }
  return blocks;
}

// The email to send (approved email leads) and the Slack message update.
const config = $('Config').first().json;
const d = $('Read decision').first().json;
const r = $input.first().json;
const out = [];

let outcome;
if (!r.changed) {
  outcome = `:information_source: Already ${r.status}${r.decided_by ? ' by ' + r.decided_by : ''}. No change made.`;
} else if (!d.approved) {
  outcome = `:x: Rejected by ${d.user}. Nothing was sent; the lead is yours to follow up.`;
} else if (r.unsubscribed) {
  outcome = `:no_entry: Approved by ${d.user}, but the lead has unsubscribed, so nothing was sent.`;
} else if (r.channel === 'email') {
  const to = String(r.lead.email || '').toLowerCase();
  if (config.allowlist.includes(to)) {
    out.push({ json: { kind: 'email', to, subject: r.subject, reply: r.reply, thread_id: r.thread_id, in_reply_to: null } });
    outcome = `:white_check_mark: Approved by ${d.user} and emailed to the customer.`;
  } else {
    outcome = `:white_check_mark: Approved by ${d.user}, but not emailed: ${to} isn't on OUTBOUND_EMAIL_ALLOWLIST.`;
  }
} else {
  outcome = `:white_check_mark: Approved by ${d.user} and sent to the customer's web thread.`;
}

const p = { approval_id: d.approval_id, who: whoLine(r.lead), summary: r.lead.summary, reply: r.reply };
out.push({ json: { kind: 'slack', body: { channel: d.channel, ts: d.message_ts, text: outcome,
                                          blocks: priceApprovalBlocks(p, outcome) } } });
return out;

// Build the Gmail message: plain text, UTF-8, in the lead's thread.
const config = $('Config').first().json;
const item = $json;
const b64 = s => Buffer.from(s, 'utf8').toString('base64');

const base = item.subject || 'Your request';
const subject = /^re:/i.test(base) ? base : 'Re: ' + base;
const headers = [
  `From: =?UTF-8?B?${b64(config.company_name + ' (demo)')}?= <${config.intake_address}>`,
  `To: ${item.to}`,
  `Subject: =?UTF-8?B?${b64(subject)}?=`,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
];
if (item.in_reply_to) headers.push(`In-Reply-To: ${item.in_reply_to}`, `References: ${item.in_reply_to}`);

const text = `${item.reply}\n\n${config.email_footer}`;
const mime = headers.join('\r\n') + '\r\n\r\n' + b64(text).replace(/(.{76})/g, '$1\r\n');
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

return { json: { send: item.thread_id ? { raw, threadId: item.thread_id } : { raw } } };
